/*
 * A339562  Squarefree numbers with no prime index dividing all the other
 *          prime indices.
 * https://oeis.org/A339562
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 37, u16 n <= 55, u32 n <= 55, u64 n <= 55, u128 n <= 55,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*  A339562 – Squarefree numbers with no prime index dividing all the other prime indices.
 *
 *  The sequence is generated by direct inspection of successive integers.
 *  For each integer n > 1 we:
 *      1.  check that n is square‑free;
 *      2.  collect the 1‑based indices of its prime divisors;
 *      3.  let m be the smallest of these indices;
 *      4.  include n iff there exists an index not divisible by m.
 *
 *  The table is built incrementally and memoised so that any order of
 *  calls to a(idx_t n) works.  A simple sieve up to a fixed limit
 *  supplies prime factorisation data.
 *
 *  This implementation meets the required time and space constraints
 *  for n up to about 10 000 and works for any of the supported seq_t
 *  types.
 *
 *  Implementation assumptions:
 *      – seq_t and idx_t are defined by the build system.
 *      – SIEVE_LIMIT covers all numbers that may be needed for the
 *        requested range (≈ 2 000 000 is sufficient for n ≤ 10 000).
 */

#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* --------------------------------------------------------------------- */
/*  Sieve data                                                          */
/* --------------------------------------------------------------------- */
static bool sieve_inited = false;
static uint32_t *spf        = NULL;   /* spf[i] = smallest prime factor of i   */
static uint32_t *prime_idx  = NULL;   /* prime_idx[p] = 1‑based prime index    */
static uint32_t *primes     = NULL;   /* list of primes                       */
static uint32_t  primes_cnt = 0;
static uint32_t  primes_cap = 0;

#define SIEVE_LIMIT 2000000   /* large enough for n ≤ 10 000 */

static void init_sieve(void)
{
    if (sieve_inited)
        return;

    spf        = (uint32_t*)calloc(SIEVE_LIMIT + 1, sizeof(uint32_t));
    prime_idx  = (uint32_t*)calloc(SIEVE_LIMIT + 1, sizeof(uint32_t));
    primes_cap = 500000;          /* initial capacity for the prime list */
    primes     = (uint32_t*)malloc(primes_cap * sizeof(uint32_t));

    for (uint32_t i = 2; i <= SIEVE_LIMIT; ++i)
    {
        if (spf[i] == 0)          /* i is prime */
        {
            spf[i] = i;
            if (primes_cnt == primes_cap)
            {
                primes_cap <<= 1;
                primes = (uint32_t*)realloc(primes, primes_cap * sizeof(uint32_t));
            }
            primes[primes_cnt] = i;
            prime_idx[i] = ++primes_cnt;   /* 1‑based index of prime i */
        }
        for (uint32_t j = 0; j < primes_cnt && (uint64_t)i * primes[j] <= SIEVE_LIMIT; ++j)
        {
            uint32_t v = i * primes[j];
            if (spf[v] == 0)
                spf[v] = primes[j];
            if (i % primes[j] == 0)
                break;
        }
    }
    sieve_inited = true;
}

/* --------------------------------------------------------------------- */
/*  Memoised sequence                                                   */
/* --------------------------------------------------------------------- */
static seq_t *seq_arr   = NULL;   /* holds the sequence including the first term 1   */
static size_t seq_cap   = 0;
static size_t seq_len   = 0;
static idx_t  last_checked = 1;   /* last integer examined by the sieve */

static void seq_append(seq_t val)
{
    if (seq_len == seq_cap)
    {
        size_t new_cap = seq_cap ? seq_cap * 2 : 16;
        seq_arr = (seq_t*)realloc(seq_arr, new_cap * sizeof(seq_t));
        seq_cap = new_cap;
    }
    seq_arr[seq_len++] = val;
}

static void init_sequence(void)
{
    if (!sieve_inited)
        init_sieve();
    if (seq_arr == NULL)
    {
        seq_arr = (seq_t*)malloc(16 * sizeof(seq_t));
        seq_cap = 16;
        seq_len = 0;
    }
    if (seq_len == 0)
    {
        seq_arr[0] = (seq_t)1;   /* the first term of the sequence */
        seq_len = 1;
    }
}

/* --------------------------------------------------------------------- */
/*  Main sequence function                                              */
/* --------------------------------------------------------------------- */
seq_t a(idx_t n)
{
    if (n == 1)
        return (seq_t)1; /* returned directly to avoid seeding when n==1 */

    init_sequence();

    /* Produce terms up to the desired index. */
    while (seq_len < (size_t)n)
    {
        ++last_checked;
        if (last_checked > SIEVE_LIMIT)
            return (seq_t)0; /* out of sieve range – should not happen for n ≤ 10 000 */

        /* Factorise last_checked using the pre‑computed smallest prime factors. */
        idx_t tmp = last_checked;
        bool squarefree = true;
        uint32_t indices[32];
        uint32_t idx_cnt = 0;

        while (tmp > 1)
        {
            uint32_t p = spf[(uint32_t)tmp];
            uint32_t ind = prime_idx[p];
            indices[idx_cnt++] = ind;

            tmp /= p;
            if (tmp % p == 0)       /* prime factor repeated → not square‑free */
            {
                squarefree = false;
                break;
            }
        }
        if (!squarefree)
            continue;   /* skip non‑square‑free numbers */

        /* Find the smallest prime index. */
        uint32_t min_idx = indices[0];
        for (uint32_t i = 1; i < idx_cnt; ++i)
            if (indices[i] < min_idx)
                min_idx = indices[i];

        /* Check whether the smallest index divides all others. */
        bool all_div = true;
        for (uint32_t i = 0; i < idx_cnt; ++i)
        {
            if (indices[i] % min_idx != 0)
            {
                all_div = false;
                break;
            }
        }
        if (all_div)
            continue;   /* condition fails – omit this integer */

        /* Valid term – append to the sequence. */
        seq_append((seq_t)last_checked);
    }

    return seq_arr[n - 1];
}
